const fs=require('fs');const path=require('path');const ROOT=path.resolve(__dirname,'..');const MARK='CE_DATA_WAVE2A_20260809';
function insert(rel,anchor,block){const p=path.join(ROOT,rel);let s=fs.readFileSync(p,'utf8');if(s.includes(MARK+':'+rel))return false;if(!s.includes(anchor))throw new Error(`Ancre introuvable ${rel}`);s=s.replace(anchor,`<!-- ${MARK}:${rel} -->\n${block}\n${anchor}`);fs.writeFileSync(p,s,'utf8');return true;}
insert('dossiers/finances-residence-principale.html','<h2>1. La première question : combien de temps ce logement doit-il fonctionner pour vous ?</h2>',`<div class="case-study" id="marche-immobilier-2026"><h2>Le marché début 2026 : des prix nationaux presque stables, mais un marché local peut raconter autre chose</h2><p><strong>Données Notaires–Insee, premier trimestre 2026.</strong> Les prix des logements anciens en France (hors Mayotte) progressent de <strong>0,2 % sur le trimestre</strong> et de seulement <strong>0,1 % sur un an</strong>. Sur un an, les appartements progressent de 0,6 % tandis que les maisons reculent de 0,2 %. Fin mars 2026, environ <strong>952 000 transactions</strong> ont été réalisées sur les douze derniers mois.</p><div class="compare-wrap"><table class="compare-table"><thead><tr><th>Repère national</th><th>Valeur</th><th>Ce qu'il ne faut pas en déduire</th></tr></thead><tbody><tr><td>Prix ancien · T1 2026 vs T4 2025</td><td><strong>+0,2 %</strong></td><td>Votre ville ou votre type de bien peut évoluer très différemment.</td></tr><tr><td>Prix ancien · sur un an</td><td><strong>+0,1 %</strong></td><td>Une quasi-stabilité nationale ne garantit pas le prix de revente individuel.</td></tr><tr><td>Transactions sur 12 mois à fin mars</td><td><strong>952 000</strong></td><td>Le volume renseigne sur le marché global, pas sur la liquidité d'un logement précis.</td></tr></tbody></table></div><p><strong>Conséquence pour acheter ou louer :</strong> il est imprudent de rendre l'achat « gagnant » uniquement grâce à une forte hausse future du prix. Le scénario central doit pouvoir tenir avec une valorisation faible ou nulle sur quelques années.</p><p class="source-note">Source : <a href="https://www.insee.fr/fr/statistiques/8995299" rel="noopener noreferrer">Insee / Notaires de France — prix des logements anciens, T1 2026</a>, 28 mai 2026.</p></div><div class="case-study" id="hcsf-2026"><h2>Financement : 35 % et 25 ans sont des limites d'octroi, pas un budget conseillé</h2><p>La mesure HCSF en vigueur fixe en principe un <strong>taux d'effort maximal de 35 %</strong> et une <strong>maturité maximale de 25 ans</strong>, avec des cas particuliers et une marge de flexibilité pouvant représenter jusqu'à 20 % de la production trimestrielle des banques. Une banque reste libre de refuser un dossier respectant ces limites.</p><p>Exemple simple : avec 4 000 € de revenus mensuels retenus dans le calcul, 35 % représentent <strong>1 400 € de charges d'emprunt</strong>. Cela ne signifie pas qu'un ménage devrait consacrer 1 400 € à sa dette : le reste à vivre, les enfants, les projets, la stabilité des revenus et la réserve de sécurité peuvent rendre un niveau inférieur beaucoup plus raisonnable.</p><p class="source-note">Source : <a href="https://www.economie.gouv.fr/hcsf/mesures/mesure-relative-loctroi-de-credits-immobiliers" rel="noopener noreferrer">HCSF — mesure relative à l'octroi de crédits immobiliers</a>, mesure en vigueur consultée en août 2026.</p></div>`);
insert('dossiers/finances-investissement-locatif.html','<h2>1. Le premier filtre : existe-t-il vraiment une demande ?</h2>',`<div class="case-study" id="irl-2026"><h2>Loyer : +1,15 % d'IRL ne transforme pas une mauvaise opération en bonne opération</h2><p><strong>Donnée Insee, deuxième trimestre 2026.</strong> L'indice de référence des loyers (IRL) s'établit à <strong>148,37</strong> et progresse de <strong>1,15 % sur un an</strong>. Dans un bail où la révision est possible et correctement prévue, ce repère permet de mesurer l'ordre de grandeur d'une revalorisation.</p><div class="compare-wrap"><table class="compare-table"><thead><tr><th>Loyer mensuel avant révision</th><th>Hausse de 1,15 %</th><th>Nouveau loyer indicatif</th><th>Gain annuel brut</th></tr></thead><tbody><tr><td>700 €</td><td>8,05 €</td><td>708,05 €</td><td>96,60 €</td></tr><tr><td>900 €</td><td>10,35 €</td><td>910,35 €</td><td>124,20 €</td></tr><tr><td>1 200 €</td><td>13,80 €</td><td>1 213,80 €</td><td>165,60 €</td></tr></tbody></table></div><p>Sur un loyer de 900 €, une hausse de 1,15 % apporte environ <strong>124 € de recettes brutes supplémentaires sur un an</strong>. Une seule facture de plomberie, quelques jours de vacance ou une hausse de taxe foncière peuvent absorber davantage. Le rendement doit donc reposer d'abord sur le prix d'achat et les charges, pas sur l'espoir de fortes revalorisations de loyer.</p><p><strong>Attention :</strong> ce calcul illustre seulement l'effet arithmétique de l'IRL. La possibilité et les modalités de révision dépendent du bail, du logement et des règles applicables au moment de la révision.</p><p class="source-note">Source : <a href="https://www.insee.fr/fr/statistiques/9022797" rel="noopener noreferrer">Insee — IRL, deuxième trimestre 2026</a>, publié le 10 juillet 2026.</p></div>`);
const dp=path.join(ROOT,'assets/editorial-data.json');const d=JSON.parse(fs.readFileSync(dp,'utf8'));d.meta.lastChecked='2026-08-09';d.realEstate={asOf:'2026-Q1',oldHousingFrance:{quarterlyChangePct:0.2,annualChangePct:0.1,apartmentsAnnualPct:0.6,housesAnnualPct:-0.2,transactions12mEndMarch2026:952000,status:'observed-provisional',source:'https://www.insee.fr/fr/statistiques/8995299'},mortgageRules:{maxEffortRatePct:35,maxMaturityYears:25,bankFlexibilitySharePct:20,status:'regulatory-current',source:'https://www.economie.gouv.fr/hcsf/mesures/mesure-relative-loctroi-de-credits-immobiliers'},irl2026Q2:{index:148.37,annualChangePct:1.15,status:'observed',source:'https://www.insee.fr/fr/statistiques/9022797'}};fs.writeFileSync(dp,JSON.stringify(d,null,2)+'\n');
